using System.Diagnostics;
using TutorFlow.Core.Autorizacion;
using TutorFlow.Core.Conocimiento;

namespace TutorFlow.Core.Asistente;

public sealed record PreguntaEntrada(string Pregunta, Usuario Usuario);

public sealed record RespuestaAsistente(
    string Respuesta,
    IReadOnlyList<Cita> Citas,
    bool UsoDatosEstudiante,
    int Tokens,
    decimal CostoUsd);

public enum TipoResultadoPregunta
{
    Respondida,
    Denegada,
    NoDisponible
}

public sealed record ResultadoPregunta(
    TipoResultadoPregunta Tipo,
    RespuestaAsistente? Respuesta,
    ResultadoAuditoria Auditoria,
    MotivoDenegacion? Motivo);

public sealed class LimitesAsistente
{
    public int MaximoCaracteresPregunta { get; init; } = 1000;
    public int MaximoBytesCuerpo { get; init; } = 16 * 1024;
    public int PreguntasPorMinutoPorIp { get; init; } = 60;
    public int MaximoSeccionesRecuperadas { get; init; } = 6;
    public int MaximoTokensSalida { get; init; } = 2000;
    public int MaximoInvocacionesHerramientas { get; init; } = 4;
    public int TimeoutLlmSegundos { get; init; } = 20;
    public int PresupuestoApiAcademicaSegundos { get; init; } = 6;
    public decimal PresupuestoDiarioUsd { get; init; } = 5m;
    public int MaximoIdentidadesPorIp { get; init; } = 3;
    public int VentanaIdentidadesMinutos { get; init; } = 10;
    public bool BloquearMultiplesIdentidades { get; init; }
}

public sealed class PreguntarAsistente
{
    private readonly IApiAcademica _apiAcademica;
    private readonly IClienteLlm _clienteLlm;
    private readonly IBaseConocimiento _baseConocimiento;
    private readonly AuditorPeticiones _auditor;
    private readonly PoliticaAcceso _politicaAcceso;
    private readonly VerificadorSalida _verificadorSalida;
    private readonly LimitesAsistente _limites;
    private readonly ConfiguracionAsistente _configuracion;
    private readonly PresupuestoDiario _presupuesto;

    public PreguntarAsistente(
        IApiAcademica apiAcademica,
        IClienteLlm clienteLlm,
        IBaseConocimiento baseConocimiento,
        AuditorPeticiones auditor,
        PoliticaAcceso politicaAcceso,
        VerificadorSalida verificadorSalida,
        LimitesAsistente limites,
        ConfiguracionAsistente configuracion,
        PresupuestoDiario presupuesto)
    {
        _apiAcademica = apiAcademica;
        _clienteLlm = clienteLlm;
        _baseConocimiento = baseConocimiento;
        _auditor = auditor;
        _politicaAcceso = politicaAcceso;
        _verificadorSalida = verificadorSalida;
        _limites = limites;
        _configuracion = configuracion;
        _presupuesto = presupuesto;
    }

    public async Task<ResultadoPregunta> EjecutarAsync(
        PreguntaEntrada entrada,
        string ipOrigen,
        string correlationId,
        CancellationToken cancellationToken)
    {
        var presupuestoApi = TimeSpan.FromSeconds(_limites.PresupuestoApiAcademicaSegundos);
        var sesion = new SesionPregunta(entrada, ipOrigen, correlationId, new ApiAcademicaConPresupuesto(_apiAcademica, presupuestoApi));
        sesion.Directorio = await ConstructorDirectorio.ConstruirAsync(entrada.Usuario, sesion.Api, _configuracion.CodigosAsignatura, cancellationToken);
        var decision = Autorizar(sesion);
        if (!decision.Permitido)
        {
            return Denegar(sesion, decision.Motivo, 0);
        }

        return _presupuesto.Agotado
            ? NoDisponible(sesion, ResultadoAuditoria.Error)
            : await ResponderAsync(sesion, cancellationToken);
    }

    private DecisionAcceso Autorizar(SesionPregunta sesion)
    {
        if (sesion.Directorio is not { } directorio)
        {
            return DecisionAcceso.Denegar(MotivoDenegacion.IdentidadInvalida);
        }

        var identidad = _politicaAcceso.EvaluarIdentidad(sesion.Entrada.Usuario, directorio);
        return identidad.Permitido
            ? _politicaAcceso.EvaluarPregunta(sesion.Entrada.Usuario, sesion.Entrada.Pregunta, directorio)
            : identidad;
    }

    private async Task<ResultadoPregunta> ResponderAsync(SesionPregunta sesion, CancellationToken cancellationToken)
    {
        var directorio = sesion.Directorio!;
        var secciones = _baseConocimiento.BuscarSecciones(ConsultaDeRecuperacion.DeTexto(sesion.Entrada.Pregunta), _limites.MaximoSeccionesRecuperadas);
        var conversacion = new ConversacionLlm(_clienteLlm, new HerramientasAsistente(sesion.Api, _politicaAcceso), _limites, _configuracion);
        var contexto = new ContextoUsuario(sesion.Entrada.Usuario, directorio);
        var resultado = await conversacion.EjecutarAsync(contexto, sesion.Entrada.Pregunta, secciones, sesion.Registro, cancellationToken);
        sesion.Uso = resultado.Uso;
        _presupuesto.Registrar(CalculadoraCosto.Calcular(resultado.Uso, _configuracion.Precio));
        return resultado.Estado switch
        {
            EstadoConversacion.IdAjeno => Denegar(sesion, MotivoDenegacion.HerramientaIdAjeno, resultado.Uso.Total),
            EstadoConversacion.LimiteHerramientas => NoDisponible(sesion, ResultadoAuditoria.LimiteHerramientas),
            EstadoConversacion.Rechazada => Responder(sesion, Textos.NoVerificable, [], ResultadoAuditoria.Error),
            _ => Completar(sesion, resultado.Texto ?? string.Empty, secciones)
        };
    }

    private ResultadoPregunta Completar(SesionPregunta sesion, string texto, IReadOnlyList<SeccionDocumento> secciones)
    {
        if (texto.Trim() == Textos.SinInformacion)
        {
            return Responder(sesion, Textos.SinInformacion, [], ResultadoAuditoria.SinInformacion, usoDatos: false);
        }

        var fundamentos = _baseConocimiento.BuscarSecciones(ConsultaDeRecuperacion.DeTexto(texto), _limites.MaximoSeccionesRecuperadas);
        foreach (var seccion in secciones.Concat(fundamentos))
        {
            sesion.Registro.AgregarFuente($"{seccion.Titulo}. {seccion.Texto}");
        }

        var directorio = sesion.Directorio!;
        var autorizados = _politicaAcceso.IdsPersonasAutorizadas(sesion.Entrada.Usuario, directorio);
        var candidatas = ElegirCitasNormativas(texto, fundamentos, secciones);
        var verificada = _verificadorSalida.Verificar(sesion.Entrada.Usuario, texto, candidatas, autorizados, sesion.Registro.Fuentes, _baseConocimiento, directorio);
        return Responder(sesion, verificada.Respuesta, CitasFinales(sesion, verificada), verificada.Resultado);
    }

    private IReadOnlyList<Cita> CitasFinales(SesionPregunta sesion, SalidaVerificada verificada)
    {
        if (verificada.Resultado != ResultadoAuditoria.Respondida)
        {
            return verificada.Citas;
        }

        var reglas = _verificadorSalida.DescartarCitasInexistentes(sesion.Registro.Reglas, _baseConocimiento);
        return [.. verificada.Citas.Concat(reglas).Concat(sesion.Registro.Citas).Distinct()];
    }

    private IReadOnlyList<Cita> ElegirCitasNormativas(string texto, IReadOnlyList<SeccionDocumento> fundamentos, IReadOnlyList<SeccionDocumento> secciones)
    {
        var explicitas = _verificadorSalida.DescartarCitasInexistentes(ExtractorCitas.De(texto), _baseConocimiento);
        return explicitas.Count > 0
            ? explicitas
            : [.. fundamentos.Concat(secciones).Select(s => new Cita(s.Documento, s.Seccion)).Distinct()];
    }

    private ResultadoPregunta Responder(
        SesionPregunta sesion,
        string texto,
        IReadOnlyList<Cita> citas,
        ResultadoAuditoria resultado,
        bool? usoDatos = null)
    {
        var respuesta = new RespuestaAsistente(
            texto,
            citas,
            usoDatos ?? sesion.Registro.UsoDatos,
            sesion.Uso.Total,
            CalculadoraCosto.Calcular(sesion.Uso, _configuracion.Precio));
        Auditar(sesion, resultado, null, citas);
        return new ResultadoPregunta(TipoResultadoPregunta.Respondida, respuesta, resultado, null);
    }

    private ResultadoPregunta Denegar(SesionPregunta sesion, MotivoDenegacion? motivo, int tokens)
    {
        var costo = CalculadoraCosto.Calcular(sesion.Uso, _configuracion.Precio);
        var citas = new[] { Textos.CitaNegativa() };
        var respuesta = new RespuestaAsistente(Textos.Negativa(sesion.Entrada.Usuario.Rol), citas, false, tokens, costo);
        Auditar(sesion, ResultadoAuditoria.Denegada, motivo, citas);
        return new ResultadoPregunta(TipoResultadoPregunta.Denegada, respuesta, ResultadoAuditoria.Denegada, motivo);
    }

    private ResultadoPregunta NoDisponible(SesionPregunta sesion, ResultadoAuditoria resultado)
    {
        Auditar(sesion, resultado, null, []);
        return new ResultadoPregunta(TipoResultadoPregunta.NoDisponible, null, resultado, null);
    }

    private void Auditar(SesionPregunta sesion, ResultadoAuditoria resultado, MotivoDenegacion? motivo, IReadOnlyList<Cita> citas)
    {
        var usuario = sesion.Entrada.Usuario;
        var pregunta = AuditorPeticiones.SanearPregunta(usuario, sesion.Entrada.Pregunta, sesion.Directorio ?? ConstructorDirectorio.Vacio);
        var costo = CalculadoraCosto.Calcular(sesion.Uso, _configuracion.Precio);
        var registro = sesion.Registro;
        _auditor.Registrar(new EventoAuditoria(
            _auditor.AhoraUtc, sesion.CorrelationId, sesion.IpOrigen, usuario.Rol, usuario.Id, pregunta, resultado, motivo,
            registro.Estudiantes, registro.Recursos, citas, sesion.Uso.Total, costo,
            sesion.Cronometro.ElapsedMilliseconds, _configuracion.Precio is null)
        {
            DatosConsultados = registro.DatosConsultados
        });
    }

    private sealed class SesionPregunta(PreguntaEntrada entrada, string ipOrigen, string correlationId, ApiAcademicaConPresupuesto api)
    {
        public PreguntaEntrada Entrada { get; } = entrada;

        public string IpOrigen { get; } = ipOrigen;

        public string CorrelationId { get; } = correlationId;

        public ApiAcademicaConPresupuesto Api { get; } = api;

        public Stopwatch Cronometro { get; } = Stopwatch.StartNew();

        public RegistroConsultas Registro { get; } = new();

        public DirectorioAcademico? Directorio { get; set; }

        public UsoTokens Uso { get; set; } = new(0, 0);
    }
}
using System.Diagnostics;
using TutorFlow.Core.Asistente;
using TutorFlow.Core.Autorizacion;

namespace TutorFlow.Api;

public sealed partial class ProcesadorPregunta
{
    private const string TituloSolicitudInvalida = "La solicitud no es válida.";
    private const string TituloCuerpoDemasiadoGrande = "El cuerpo de la solicitud supera el tamaño permitido.";
    private const string TituloDemasiadasSolicitudes = "Se superó el límite de preguntas. Intenta de nuevo más tarde.";
    private const string TituloServicioNoDisponible = "El servicio no está disponible en este momento. Intenta de nuevo.";

    private readonly LimitesAsistente _limites;
    private readonly LimitadorTasaPorIp _limitadorTasa;
    private readonly LimitadorIdentidades _limitadorIdentidades;
    private readonly AuditorPeticiones _auditor;
    private readonly PreguntarAsistente _preguntarAsistente;
    private readonly ILogger<ProcesadorPregunta> _logger;

    public ProcesadorPregunta(
        LimitesAsistente limites,
        LimitadorTasaPorIp limitadorTasa,
        LimitadorIdentidades limitadorIdentidades,
        AuditorPeticiones auditor,
        PreguntarAsistente preguntarAsistente,
        ILogger<ProcesadorPregunta> logger)
    {
        _limites = limites;
        _limitadorTasa = limitadorTasa;
        _limitadorIdentidades = limitadorIdentidades;
        _auditor = auditor;
        _preguntarAsistente = preguntarAsistente;
        _logger = logger;
    }

    public async Task<IResult> ProcesarAsync(HttpContext contexto, CancellationToken cancellationToken)
    {
        var peticion = new DatosPeticion(IpDe(contexto), contexto.TraceIdentifier, Stopwatch.StartNew());
        var tasa = _limitadorTasa.Intentar(peticion.Ip);
        if (!tasa.Permitido)
        {
            return Rechazar429(contexto, peticion, null, tasa.SegundosParaReintentar);
        }

        var cuerpo = await LectorCuerpo.LeerAsync(contexto.Request.Body, _limites.MaximoBytesCuerpo, cancellationToken);
        if (cuerpo.ExcedeElLimite)
        {
            return RechazarInvalida(peticion, null, StatusCodes.Status413PayloadTooLarge, TituloCuerpoDemasiadoGrande);
        }

        var solicitud = ValidadorSolicitud.Validar(cuerpo.Bytes, _limites.MaximoCaracteresPregunta);
        return solicitud.EsValida
            ? await ResponderAsync(contexto, peticion, solicitud, cancellationToken)
            : RechazarInvalida(peticion, solicitud.Pregunta, StatusCodes.Status400BadRequest, TituloSolicitudInvalida);
    }

    private static string IpDe(HttpContext contexto)
    {
        var direccion = contexto.Connection.RemoteIpAddress;
        if (direccion is null)
        {
            return "desconocida";
        }

        return (direccion.IsIPv4MappedToIPv6 ? direccion.MapToIPv4() : direccion).ToString();
    }

    private async Task<IResult> ResponderAsync(HttpContext contexto, DatosPeticion peticion, SolicitudValidada solicitud, CancellationToken cancellationToken)
    {
        var usuario = new Usuario(solicitud.Rol!.Value, solicitud.UsuarioId!);
        var identidades = _limitadorIdentidades.Registrar(peticion.Ip, usuario.Id);
        if (identidades.SuperacionNueva)
        {
            _auditor.RegistrarMultiplesIdentidades(peticion.Ip, identidades.Ids);
        }

        if (identidades.Superado && _limites.BloquearMultiplesIdentidades)
        {
            return Rechazar429(contexto, peticion, solicitud, (int)TimeSpan.FromMinutes(_limites.VentanaIdentidadesMinutos).TotalSeconds);
        }

        return await PreguntarAsync(peticion, new PreguntaEntrada(solicitud.Pregunta!, usuario), cancellationToken);
    }

    private async Task<IResult> PreguntarAsync(DatosPeticion peticion, PreguntaEntrada entrada, CancellationToken cancellationToken)
    {
        try
        {
            var resultado = await _preguntarAsistente.EjecutarAsync(entrada, peticion.Ip, peticion.CorrelationId, cancellationToken);
            return Mapear(resultado);
        }
        catch (Exception excepcion) when (EsFalloDeDependencia(excepcion, cancellationToken))
        {
            RegistrarDependenciaCaida(_logger, excepcion.GetType().Name);
            RegistrarError(peticion, entrada);
            return Results.Problem(statusCode: StatusCodes.Status503ServiceUnavailable, title: TituloServicioNoDisponible);
        }
        catch (Exception)
        {
            RegistrarError(peticion, entrada);
            throw;
        }
    }

    private static bool EsFalloDeDependencia(Exception excepcion, CancellationToken cancellationToken) =>
        excepcion is DependenciaNoDisponibleException or HttpRequestException or TimeoutException
        || (excepcion is OperationCanceledException && !cancellationToken.IsCancellationRequested);

    private void RegistrarError(DatosPeticion peticion, PreguntaEntrada entrada) =>
        _auditor.RegistrarSinConsultas(new SolicitudAuditoria(
            peticion.Ip,
            peticion.CorrelationId,
            entrada.Usuario.Rol,
            entrada.Usuario.Id,
            entrada.Pregunta,
            ResultadoAuditoria.Error,
            peticion.Cronometro.ElapsedMilliseconds));

    private static IResult Mapear(ResultadoPregunta resultado)
    {
        if (resultado.Respuesta is not { } respuesta)
        {
            return Results.Problem(statusCode: StatusCodes.Status503ServiceUnavailable, title: TituloServicioNoDisponible);
        }

        var cuerpo = new PreguntaRespuesta(
            respuesta.Respuesta,
            [.. respuesta.Citas.Select(cita => new CitaRespuesta(cita.Documento, cita.Seccion))],
            respuesta.UsoDatosEstudiante,
            respuesta.Tokens,
            respuesta.CostoUsd);
        var estado = resultado.Tipo == TipoResultadoPregunta.Denegada ? StatusCodes.Status403Forbidden : StatusCodes.Status200OK;
        return Results.Json(cuerpo, statusCode: estado);
    }

    private IResult RechazarInvalida(DatosPeticion peticion, string? pregunta, int estado, string titulo)
    {
        _auditor.RegistrarSinConsultas(new SolicitudAuditoria(
            peticion.Ip,
            peticion.CorrelationId,
            null,
            null,
            pregunta,
            ResultadoAuditoria.Invalida,
            peticion.Cronometro.ElapsedMilliseconds));
        return Results.Problem(statusCode: estado, title: titulo);
    }

    private IResult Rechazar429(HttpContext contexto, DatosPeticion peticion, SolicitudValidada? solicitud, int segundosParaReintentar)
    {
        _auditor.RegistrarSinConsultas(new SolicitudAuditoria(
            peticion.Ip,
            peticion.CorrelationId,
            solicitud?.Rol,
            solicitud?.UsuarioId,
            solicitud?.Pregunta,
            ResultadoAuditoria.Denegada,
            peticion.Cronometro.ElapsedMilliseconds));
        contexto.Response.Headers.RetryAfter = segundosParaReintentar.ToString(System.Globalization.CultureInfo.InvariantCulture);
        return Results.Problem(statusCode: StatusCodes.Status429TooManyRequests, title: TituloDemasiadasSolicitudes);
    }

    [LoggerMessage(Level = LogLevel.Warning, Message = "Una dependencia no respondió ({TipoDeError}).")]
    private static partial void RegistrarDependenciaCaida(ILogger logger, string tipoDeError);

    private sealed record DatosPeticion(string Ip, string CorrelationId, Stopwatch Cronometro);
}
namespace TutorFlow.Core.Autorizacion;

public sealed class PoliticaAcceso
{
    private static readonly DecisionAcceso AccesoPermitido = DecisionAcceso.Permitir();
    private readonly DecisionAcceso _decisionPermitida = AccesoPermitido;

    public DecisionAcceso EvaluarIdentidad(Usuario usuario, DirectorioAcademico directorio) =>
        ExisteIdentidad(usuario, directorio)
            ? _decisionPermitida
            : DecisionAcceso.Denegar(MotivoDenegacion.IdentidadInvalida);

    public DecisionAcceso EvaluarPregunta(Usuario usuario, string pregunta, DirectorioAcademico directorio)
    {
        var texto = NormalizadorTexto.Normalizar(pregunta);
        var motivo = MotivoTercero(usuario, texto, directorio)
            ?? MotivoPrograma(usuario, texto, directorio)
            ?? MotivoAgregado(usuario, texto);
        return motivo is { } denegado ? DecisionAcceso.Denegar(denegado) : DecisionAcceso.Permitir();
    }

    public DecisionAcceso EvaluarLecturaEstudiante(Usuario usuario, string estudianteId, DirectorioAcademico directorio) =>
        PuedeLeerEstudiante(usuario, estudianteId, directorio)
            ? DecisionAcceso.Permitir()
            : DecisionAcceso.Denegar(MotivoDenegacion.HerramientaIdAjeno);

    public IReadOnlyList<string> ProgramasAutorizados(Usuario usuario, DirectorioAcademico directorio) =>
        EvaluarIdentidad(usuario, directorio).Permitido ? AmbitoPersonal.ProgramasDe(usuario, directorio) : [];

    public IReadOnlyList<string> IdsPersonasAutorizadas(Usuario usuario, DirectorioAcademico directorio)
    {
        if (!EvaluarIdentidad(usuario, directorio).Permitido)
        {
            return [];
        }

        var ambito = AmbitoPersonal.De(usuario, directorio);
        return [.. directorio.Estudiantes.Select(e => e.Id)
            .Concat(directorio.Coordinadores.Select(c => c.Id))
            .Where(id => ambito.ClavesDeNombre.Contains(AmbitoPersonal.Clave(id)))];
    }

    private static bool ExisteIdentidad(Usuario usuario, DirectorioAcademico directorio) => usuario.Rol switch
    {
        Rol.Estudiante => Identificadores.EsIdEstudiante(usuario.Id) && directorio.Estudiantes.Any(e => e.Id == usuario.Id),
        Rol.Coordinador => Identificadores.EsIdCoordinador(usuario.Id) && directorio.Coordinadores.Any(c => c.Id == usuario.Id),
        _ => false
    };

    private bool PuedeLeerEstudiante(Usuario usuario, string estudianteId, DirectorioAcademico directorio)
    {
        var estudiante = directorio.Estudiantes.FirstOrDefault(e => e.Id == estudianteId);
        if (estudiante is null || !Identificadores.EsIdEstudiante(estudianteId))
        {
            return false;
        }

        return usuario.Rol == Rol.Estudiante
            ? usuario.Id == estudianteId
            : ProgramasAutorizados(usuario, directorio).Contains(estudiante.ProgramaId);
    }

    private static MotivoDenegacion? MotivoTercero(Usuario usuario, string texto, DirectorioAcademico directorio) =>
        DetectorTerceros.MencionaTercero(usuario, texto, directorio) ? MotivoDenegacion.TerceroMencionado : null;

    private MotivoDenegacion? MotivoPrograma(Usuario usuario, string texto, DirectorioAcademico directorio) =>
        usuario.Rol == Rol.Coordinador && DetectorProgramas.MencionaProgramaAjeno(texto, ProgramasAutorizados(usuario, directorio), directorio)
            ? MotivoDenegacion.ProgramaAjeno
            : null;

    private static MotivoDenegacion? MotivoAgregado(Usuario usuario, string texto) =>
        usuario.Rol == Rol.Estudiante && DetectorAgregados.PideAgregados(texto) ? MotivoDenegacion.Agregado : null;
}

